KG_CODE("f:vendor/kgraph-2.2/kgraph/scripts/kg/extract_more.py","\"\"\"Graph extraction for the extended file universe: legacy Office, macros, email, OpenDocument, EPUB,\nCSV/TSV, notebooks, subtitles, SQLite, archives, scanned PDFs (OCR), images (metadata + OCR),\naudio/video (metadata + transcription + frame OCR), project/build files.\n\nEvery function returns {\"nodes\", \"edges\", \"pending\", [\"text\"]} like the other extractors.\n`ctx` carries the output dir (for OCR/transcript caches) and options (ocr, media, max_ocr_pages).\n\"\"\"\nfrom __future__ import annotations\n\nimport io\nimport json\nimport re\nimport shutil\nimport tempfile\nimport zipfile\nfrom pathlib import Path\n\nfrom . import extract_code, legacy, media, native, ocr, pdfparse\nfrom .ole import OleFile, vba_modules\nfrom .util import file_id, read_text, sanitize_label, slug, sym_id\n\nVBA_SHEET_RX = re.compile(r\"(?:Sheets|Worksheets|Charts)\\s*\\(\\s*\\\"([^\\\"]+)\\\"\\s*\\)\", re.I)\n\n\ndef _doc(rel, kind):\n    return {\"id\": file_id(rel), \"label\": rel.rsplit(\"/\", 1)[-1], \"type\": kind, \"source_file\": rel, \"source_location\": \"L1\"}\n\n\ndef _text_features(rel, text, res, section_fn=None):\n    from .extract_docs import _common_doc_features\n    _common_doc_features(rel, text, res[\"nodes\"], res[\"edges\"], res[\"pending\"], section_fn or (lambda off: file_id(rel)))\n\n\nNUMBERED_HEADING = re.compile(r\"^[ \\t]*((?:\\d{1,2}|[IVX]{1,4})(?:\\.\\d{1,2}){0,3})[.)\\-]?[ \\t]+([^\\n]{2,90})$\", re.M)\n\n\ndef promote_numbered_headings(text):\n    '''Plain-text documents (PDF, .doc, RTF, style-less .docx) often have numbered headings like\n    '1. \\u0627\\u0644\\u063a\\u0631\\u0636 \\u0645\\u0646 \\u0627\\u0644\\u0628\\u0637\\u0627\\u0642\\u0629' or '2.3 Scope'. Turn short, unpunctuated numbered lines into markdown headings.'''\n    if re.search(r\"^#{1,6} \", text, re.M):\n        return text\n\n    def repl(m):\n        num, title = m.group(1), m.group(2).strip()\n        if \" | \" in title or len(title.split()) > 10 or title.endswith((\".\", '\\u060c', \";\", \",\", \":\")) and len(title.split()) > 6:\n            return m.group(0)\n        depth = min(5, num.count(\".\") + 2)\n        return \"#\" * depth + \" \" + f\"{num} {title}\"\n\n    return NUMBERED_HEADING.sub(repl, text)\n\n\ndef _markdownish(rel, text, kind):\n    from .extract_docs import extract_markdown\n    text = promote_numbered_headings(text)\n    res = extract_markdown(rel, text)\n    res[\"nodes\"][0][\"type\"] = kind\n    res[\"text\"] = text\n    _mention_identifiers(rel, text, res)\n    return res\n\n\n# ------------------------------------------------------------------ images embedded in Office files\n\nOCRABLE = (\".png\", \".jpg\", \".jpeg\", \".gif\", \".bmp\", \".tif\", \".tiff\", \".emf\", \".wmf\", \".emz\", \".wmz\")\nVECTOR = (\".svg\",)\nDECORATIVE_BYTES = 6000  # email signature icons, bullets, spacer gifs\n\n\ndef _materialize_image(data_or_path, target):\n    \"\"\"Write an image to disk for OCR; compressed metafiles (.emz/.wmz) are gunzipped to .emf/.wmf.\"\"\"\n    import gzip\n    target = Path(target)\n    data = Path(data_or_path).read_bytes() if not isinstance(data_or_path, (bytes, bytearray)) else data_or_path\n    if target.suffix.lower() in (\".emz\", \".wmz\"):\n        try:\n            data = gzip.decompress(data)\n            target = target.with_suffix(\".emf\" if target.suffix.lower() == \".emz\" else \".wmf\")\n        except OSError:\n            return None\n    if not target.exists() or target.stat().st_size != len(data):\n        target.write_bytes(data)\n    return target\n\n\ndef enrich_embedded_images(rel, abs_path, ctx, res, min_bytes=8000):\n    \"\"\"OCR pictures inside .pptx/.docx/.xlsx (screenshots, scanned forms, charts with text) and attach the\n    text to the slide / document, so nothing visual inside an Office file is left unread.\"\"\"\n    if not ctx.get(\"ocr\", True) or not ocr.available() or not ctx.get(\"frames_dir\"):\n        return res\n    try:\n        z = zipfile.ZipFile(abs_path)\n    except (zipfile.BadZipFile, OSError):\n        return res\n    names = z.namelist()\n    media = [n for n in names if re.match(r\"^(ppt|word|xl)/media/\", n)]\n    if not media:\n        return res\n    vector = [n for n in media if n.lower().endswith(VECTOR)]\n    raster = [n for n in media if n.lower().endswith(OCRABLE) and z.getinfo(n).file_size >= min_bytes]\n    node = res[\"nodes\"][0]\n    node[\"embedded_images\"] = len(media)\n    skipped = [n for n in media if not n.lower().endswith(OCRABLE + VECTOR)]\n    if skipped:\n        node[\"embedded_media_other\"] = len(skipped)  # e.g. embedded video/audio/ole objects\n    if not raster and not vector:\n        return res\n    # which slide uses which picture\n    slide_of = {}\n    for n in names:\n        m = re.match(r\"^ppt/slides/_rels/slide(\\d+)\\.xml\\.rels$\", n)\n        if m:\n            for tgt in re.findall(r'Target=\"\\.\\./media/([^\"]+)\"', z.read(n).decode(\"utf-8\", \"replace\")):\n                slide_of.setdefault(\"ppt/media/\" + tgt, set()).add(int(m.group(1)))\n    out_dir = Path(ctx[\"frames_dir\"]).parent / \"embedded\" / slug(rel, 120)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    paths = {}\n    for n in raster[:400]:\n        target = _materialize_image(z.read(n), out_dir / n.replace(\"/\", \"_\"))\n        if target:\n            paths[str(target)] = n\n    svg_texts = []\n    for n in vector:  # SVG is XML: its text can be read directly\n        try:\n            t = \" \".join(re.sub(r\"<[^>]+>\", \" \", m) for m in re.findall(r\"<text[^>]*>(.*?)</text>\", z.read(n).decode(\"utf-8\", \"replace\"), re.S))\n            if t.strip():\n                svg_texts.append(re.sub(r\"\\s+\", \" \", t).strip())\n        except Exception:\n            pass\n    results = ocr.ocr_many(list(paths), ctx.get(\"ocr_cache\"))\n    blocks, readable = {}, 0\n    for p, r in results.items():\n        text = (r.get(\"text\") or \"\").strip()\n        if len(text) < 8 or r.get(\"quality\", 0) < 0.35:\n            continue\n        readable += 1\n        slides = sorted(slide_of.get(paths[p], [])) or [0]\n        for s in slides:\n            blocks.setdefault(s, []).append(text)\n    node[\"embedded_images_with_text\"] = readable\n    if svg_texts:\n        blocks.setdefault(0, []).extend(svg_texts)\n    if not blocks:\n        return res\n    parts = []\n    for s in sorted(blocks):\n        header = f\"## Slide {s} — text inside images (OCR)\" if s else \"## Text inside embedded images (OCR)\"\n        seen, uniq = set(), []\n        for t in blocks[s]:\n            if t not in seen:\n                seen.add(t)\n                uniq.append(t)\n        parts.append(header + \"\\n\" + \"\\n\\n\".join(uniq))\n    image_text = \"\\n\\n\".join(parts)\n    res[\"text\"] = (res.get(\"text\") or \"\") + \"\\n\\n\" + image_text\n    if res.get(\"digest\"):\n        res[\"digest\"] += \"\\n\\n\" + image_text\n    _mention_identifiers(rel, image_text, res, noisy=True)\n    return res\n\n\n# ------------------------------------------------------------------ macros\n\ndef attach_vba(rel, modules, res, sheets_by_name=None, sheets_by_codename=None):\n    \"\"\"Turn VBA modules found inside a container into code nodes linked to the container and its sheets.\"\"\"\n    sheets_by_name = {k.lower(): v for k, v in (sheets_by_name or {}).items()}\n    sheets_by_codename = {k.lower(): v for k, v in (sheets_by_codename or {}).items()}\n    fid = file_id(rel)\n    all_code = []\n    for m in modules:\n        code = m.get(\"code\", \"\")\n        if not code.strip():\n            continue\n        prel = f\"{rel}/vba/{m['name']}.bas\"\n        sub = extract_code.extract(prel, code, \"vba\")\n        sub[\"nodes\"][0].update(type=\"vba_module\", label=f\"{m['name']} (VBA {m.get('type', 'module')})\", container=rel)\n        res[\"nodes\"].extend(sub[\"nodes\"])\n        res[\"edges\"].extend(sub[\"edges\"])\n        res[\"pending\"].extend(sub[\"pending\"])\n        res[\"edges\"].append({\"source\": fid, \"target\": sub[\"nodes\"][0][\"id\"], \"relation\": \"contains_macro\",\n                             \"confidence\": \"EXTRACTED\", \"source_file\": rel, \"source_location\": \"\"})\n        code_behind = sheets_by_codename.get(m[\"name\"].lower())\n        if code_behind:\n            res[\"edges\"].append({\"source\": sub[\"nodes\"][0][\"id\"], \"target\": code_behind, \"relation\": \"code_behind\",\n                                 \"confidence\": \"EXTRACTED\", \"source_file\": rel, \"source_location\": \"\"})\n        funcs = [n for n in sub[\"nodes\"] if n[\"type\"] in (\"function\", \"method\")]\n        lines = code.split(\"\\n\")\n        for fm in VBA_SHEET_RX.finditer(code):\n            line_no = code.count(\"\\n\", 0, fm.start()) + 1\n            owner = sub[\"nodes\"][0][\"id\"]\n            best = -1\n            for fn in funcs:\n                start = int(fn[\"source_location\"][1:])\n                if start <= line_no and start > best:\n                    best, owner = start, fn[\"id\"]\n            target = sheets_by_name.get(fm.group(1).lower())\n            if target:\n                res[\"edges\"].append({\"source\": owner, \"target\": target, \"relation\": \"uses_sheet\", \"confidence\": \"EXTRACTED\",\n                                     \"source_file\": prel, \"source_location\": f\"L{line_no}\"})\n            elif sheets_by_name:\n                # the workbook's sheet list is known and this name is not in it: a real bug worth surfacing\n                bid = sym_id(rel, \"missing_sheet:\" + fm.group(1))\n                if not any(n[\"id\"] == bid for n in res[\"nodes\"]):\n                    res[\"nodes\"].append({\"id\": bid, \"label\": f\"{sanitize_label(fm.group(1), 80)} (missing sheet)\",\n                                         \"type\": \"broken_reference\", \"source_file\": rel, \"source_location\": \"\",\n                                         \"doc\": \"Referenced by VBA but no sheet with this name exists in the workbook\"})\n                res[\"edges\"].append({\"source\": owner, \"target\": bid, \"relation\": \"uses_sheet\", \"confidence\": \"EXTRACTED\",\n                                     \"source_file\": prel, \"source_location\": f\"L{line_no}\", \"broken\": True})\n            else:\n                res[\"pending\"].append({\"kind\": \"sheetref\", \"source\": owner, \"name\": fm.group(1), \"file\": prel,\n                                       \"line\": line_no})\n        all_code.append(f\"' ===== VBA module {m['name']} ({m.get('type')}) =====\\n{code}\")\n    res[\"nodes\"][0][\"has_vba\"] = bool(all_code)\n    if all_code:\n        res[\"nodes\"][0][\"vba_modules\"] = len(all_code)\n    return \"\\n\\n\".join(all_code)\n\n\ndef ooxml_macros(rel, abs_path):\n    try:\n        with zipfile.ZipFile(abs_path) as z:\n            names = [n for n in z.namelist() if n.lower().endswith(\"vbaproject.bin\")]\n            if not names:\n                return []\n            return vba_modules(OleFile(z.read(names[0])))\n    except Exception:\n        return []\n\n\n# ------------------------------------------------------------------ legacy Office & email\n\ndef extract_doc_legacy(rel, abs_path):\n    text, macros = legacy.doc_text(Path(abs_path).read_bytes())\n    res = _markdownish(rel, text, \"document\")\n    code = attach_vba(rel, macros, res) if macros else \"\"\n    if code:\n        res[\"text\"] += \"\\n\\n\" + code\n    return res\n\n\ndef _sheet_nodes(rel, res, sheets):\n    \"\"\"sheets: [{\"name\",\"hidden\",\"rows\"(list) or cells(dict),\"refs\":{name:count},\"formulas\",\"samples\"}]\"\"\"\n    fid = file_id(rel)\n    ids = {}\n    parts = []\n    for sh in sheets:\n        sid = sym_id(rel, \"sheet:\" + sh[\"name\"])\n        ids[sh[\"name\"]] = sid\n        node = {\"id\": sid, \"label\": f\"{sh['name']} (sheet)\", \"type\": \"sheet\", \"source_file\": rel,\n                \"source_location\": f\"sheet {sh['name']}\", \"formulas\": sh.get(\"formulas\", 0)}\n        if sh.get(\"hidden\"):\n            node[\"hidden\"] = True\n        if sh.get(\"samples\"):\n            node[\"formula_samples\"] = sh[\"samples\"]\n        res[\"nodes\"].append(node)\n        res[\"edges\"].append({\"source\": fid, \"target\": sid, \"relation\": \"contains\", \"confidence\": \"EXTRACTED\",\n                             \"source_file\": rel, \"source_location\": \"\"})\n        rows = sh.get(\"rows\")\n        if rows is None:\n            cells = sh.get(\"cells\", {})\n            grid = {}\n            for (r, c), v in cells.items():\n                grid.setdefault(r, {})[c] = v\n            rows = [[grid[r].get(c, \"\") for c in range(max(grid[r]) + 1)] for r in sorted(grid)]\n        header = next((r for r in rows if sum(1 for x in r if str(x).strip()) >= 2), None)\n        if header:\n            for ci, val in enumerate(header[:40]):\n                if str(val).strip():\n                    col = _col_name(ci)\n                    cid = sym_id(rel, f\"sheet:{sh['name']}:col:{col}\")\n                    res[\"nodes\"].append({\"id\": cid, \"label\": f\"{sanitize_label(val, 80)} [{sh['name']}!{col}]\",\n                                         \"type\": \"column\", \"source_file\": rel, \"source_location\": f\"{sh['name']}!{col}\"})\n                    res[\"edges\"].append({\"source\": sid, \"target\": cid, \"relation\": \"has_column\", \"confidence\": \"EXTRACTED\",\n                                         \"source_file\": rel, \"source_location\": \"\"})\n        parts.append(f\"## Sheet: {sh['name']}\" + (\" (hidden)\" if sh.get(\"hidden\") else \"\"))\n        parts.extend(\" | \".join(str(x) for x in r) for r in rows[:12])\n    for sh in sheets:\n        for target, cnt in (sh.get(\"refs\") or {}).items():\n            t = ids.get(target) or next((v for k, v in ids.items() if k.replace(\" \", \"_\") == target), None)\n            if t and t != ids[sh[\"name\"]]:\n                res[\"edges\"].append({\"source\": ids[sh[\"name\"]], \"target\": t, \"relation\": \"references\",\n                                     \"confidence\": \"EXTRACTED\", \"source_file\": rel,\n                                     \"source_location\": f\"{cnt} formula refs\", \"weight\": min(5, 1 + cnt // 10)})\n    return ids, \"\\n\".join(parts)\n\n\ndef _col_name(i):\n    s = \"\"\n    i += 1\n    while i:\n        i, r = divmod(i - 1, 26)\n        s = chr(65 + r) + s\n    return s\n\n\ndef extract_xls_legacy(rel, abs_path):\n    wb = legacy.xls_workbook(Path(abs_path).read_bytes())\n    res = {\"nodes\": [_doc(rel, \"workbook\")], \"edges\": [], \"pending\": []}\n    ids, text = _sheet_nodes(rel, res, wb[\"sheets\"])\n    code = attach_vba(rel, wb[\"macros\"], res, sheets_by_name=ids) if wb[\"macros\"] else \"\"\n    res[\"text\"] = text + (\"\\n\\n\" + code if code else \"\")\n    return res\n\n\ndef extract_ppt_legacy(rel, abs_path):\n    slides, macros = legacy.ppt_slides(Path(abs_path).read_bytes())\n    return _slides(rel, slides, macros)\n\n\ndef _slides(rel, slides, macros=None):\n    fid = file_id(rel)\n    res = {\"nodes\": [_doc(rel, \"presentation\")], \"edges\": [], \"pending\": []}\n    parts = []\n    for i, texts in enumerate(slides, 1):\n        title = sanitize_label(texts[0] if texts else f\"Slide {i}\", 120)\n        sid = sym_id(rel, f\"slide{i}\")\n        res[\"nodes\"].append({\"id\": sid, \"label\": f\"Slide {i}: {title}\", \"type\": \"slide\", \"source_file\": rel,\n                             \"source_location\": f\"slide {i}\"})\n        res[\"edges\"].append({\"source\": fid, \"target\": sid, \"relation\": \"contains\", \"confidence\": \"EXTRACTED\",\n                             \"source_file\": rel, \"source_location\": \"\"})\n        body = \"\\n\".join(texts[1:])\n        parts.append(f\"## Slide {i}: {title}\\n{body}\")\n    res[\"text\"] = \"\\n\\n\".join(parts)\n    _text_features(rel, res[\"text\"], res)\n    if macros:\n        res[\"text\"] += \"\\n\\n\" + attach_vba(rel, macros, res)\n    return res\n\n\ndef collapse_repeated_lines(body, min_len=40, min_repeats=3):\n    \"\"\"Long reply threads repeat the same disclaimer / signature / address block under every quoted message.\n    Keep each long line the first time; later copies of a line seen 3+ times are dropped and counted once.\"\"\"\n    lines = (body or \"\").split(\"\\n\")\n    counts = {}\n    for ln in lines:\n        key = ln.strip()\n        if len(key) >= min_len:\n            counts[key] = counts.get(key, 0) + 1\n    repeated = {k for k, c in counts.items() if c >= min_repeats}\n    if not repeated:\n        return body or \"\"\n    seen, out, dropped = set(), [], 0\n    for ln in lines:\n        key = ln.strip()\n        if key in repeated:\n            if key in seen:\n                dropped += 1\n                continue\n            seen.add(key)\n        out.append(ln)\n    if dropped:\n        out.append(f\"\\n[kgraph: {dropped} repeated copies of {len(repeated)} long lines (signatures/disclaimers in quoted \"\n                   f\"replies) were omitted]\")\n    return \"\\n\".join(out)\n\n\ndef extract_email(rel, abs_path, ctx=None):\n    ctx = ctx or {}\n    raw = Path(abs_path).read_bytes()\n    info = legacy.msg_email(raw) if rel.lower().endswith(\".msg\") else legacy.eml_email(raw)\n    fid = file_id(rel)\n    res = {\"nodes\": [_doc(rel, \"email\")], \"edges\": [], \"pending\": []}\n    res[\"nodes\"][0][\"doc\"] = sanitize_label(info.get(\"subject\") or \"\", 200)\n    if info.get(\"draft\"):\n        res[\"nodes\"][0][\"draft\"] = True\n    if info.get(\"date\"):\n        res[\"nodes\"][0][\"date\"] = info[\"date\"]\n    if info.get(\"last_modified_by\") and not info.get(\"from\"):\n        res[\"nodes\"][0][\"last_modified_by\"] = sanitize_label(info[\"last_modified_by\"], 120)\n    if not info.get(\"from\") and not info.get(\"to\"):\n        res[\"nodes\"][0][\"note\"] = \"no sender/recipients recorded\" + (\" (unsent draft)\" if info.get(\"draft\") else \"\")\n    counts = {}\n    for role, field in ((\"sent_by\", \"from\"), (\"sent_to\", \"to\"), (\"copied_to\", \"cc\")):\n        for addr in re.split(r\"[;,]\\s*\", info.get(field) or \"\"):\n            addr = addr.strip()\n            if not addr:\n                continue\n            counts[role] = counts.get(role, 0) + 1\n            if not ctx.get(\"people\"):\n                continue  # names/addresses are personal data: no person nodes unless `build --people`\n            m = re.search(r\"<([^>]+)>\", addr)\n            key = (m.group(1) if m else addr).lower()\n            pid = f\"person:{slug(key)}\"\n            res[\"nodes\"].append({\"id\": pid, \"label\": sanitize_label(re.sub(r\"\\s*<[^>]+>\", \"\", addr) or key, 120),\n                                 \"type\": \"person\", \"source_file\": \"\", \"source_location\": \"\"})\n            res[\"edges\"].append({\"source\": fid, \"target\": pid, \"relation\": role, \"confidence\": \"EXTRACTED\",\n                                 \"source_file\": rel, \"source_location\": \"\"})\n    if counts and not ctx.get(\"people\"):\n        res[\"nodes\"][0][\"recipients\"] = counts.get(\"sent_to\", 0) + counts.get(\"copied_to\", 0)\n    for att in info.get(\"attachments\", []):\n        aid = sym_id(rel, \"attachment:\" + att)\n        res[\"nodes\"].append({\"id\": aid, \"label\": sanitize_label(att, 160), \"type\": \"attachment\", \"source_file\": rel,\n                             \"source_location\": \"\"})\n        res[\"edges\"].append({\"source\": fid, \"target\": aid, \"relation\": \"has_attachment\", \"confidence\": \"EXTRACTED\",\n                             \"source_file\": rel, \"source_location\": \"\"})\n        res[\"pending\"].append({\"kind\": \"wikilink\", \"source\": aid, \"name\": att, \"file\": rel, \"relation\": \"same_file_as\"})\n    status = \" (unsent draft)\" if info.get(\"draft\") else \"\"\n    text = (f\"# {info.get('subject', '')}{status}\\nFrom: {info.get('from') or '(not recorded)'}\"\n            + (f\"\\nLast modified by: {info['last_modified_by']}\" if info.get(\"last_modified_by\") else \"\")\n            + f\"\\nTo: {info.get('to') or '(not recorded)'}\\nDate: {info.get('date', '')}\\n\\n\"\n            + collapse_repeated_lines(info.get(\"body\", \"\")))\n    _text_features(rel, text, res)\n    _mention_identifiers(rel, text, res)\n    attachment_texts = _extract_attachments(rel, info.get(\"attachment_data\") or [], ctx, res)\n    if attachment_texts:\n        text += \"\\n\\n\" + attachment_texts\n    res[\"text\"] = text\n    return res\n\n\ndef _extract_attachments(rel, items, ctx, res, depth=0, heading=\"Attachment\", relation=\"has_attachment\"):\n    \"\"\"Save each attachment and run the normal extractor on it (PDF, Office, images with OCR, nested emails…).\"\"\"\n    import hashlib\n    from .detect import categorize\n    if not items or depth > 2:\n        return \"\"\n    fid = file_id(rel)\n    base = Path(ctx[\"frames_dir\"]).parent / \"attachments\" / slug(rel, 120) if ctx.get(\"frames_dir\") else None\n    texts = []\n    for name, data in items:\n        safe = re.sub(r'[\\\\/:*?\"<>|]+', \"_\", name).strip() or \"attachment\"\n        cat, lang = categorize(Path(safe))\n        sha = hashlib.sha256(data).hexdigest()\n        prel = f\"{rel}!/{safe}\"\n        sub_res = None\n        if base and cat:\n            base.mkdir(parents=True, exist_ok=True)\n            saved = base / safe\n            if not saved.exists() or saved.stat().st_size != len(data):\n                saved.write_bytes(data)\n            entry = {\"rel\": prel, \"category\": cat, \"abs\": str(saved), \"lang\": lang}\n            try:\n                if cat == \"code\":\n                    sub_res = extract_code.extract(prel, data.decode(\"utf-8\", errors=\"replace\"), lang)\n                else:\n                    from .extract_docs import extract as doc_extract\n                    sub_res = doc_extract(entry, None, dict(ctx, attachment_depth=depth + 1))\n            except Exception as exc:\n                sub_res = {\"nodes\": [dict(_doc(prel, \"attachment\"), error=str(exc)[:200])], \"edges\": [], \"pending\": []}\n        if sub_res is None:\n            sub_res = {\"nodes\": [_doc(prel, \"attachment\")], \"edges\": [], \"pending\": []}\n        sub_node = sub_res[\"nodes\"][0]\n        sub_node.update(container=rel, content_sha=sha, attachment_of=rel, size=len(data))\n        if relation != \"has_attachment\":\n            sub_node[\"member_of_archive\"] = rel\n        res[\"nodes\"].extend(sub_res[\"nodes\"])\n        res[\"edges\"].extend(sub_res[\"edges\"])\n        res[\"pending\"].extend(sub_res[\"pending\"])\n        res[\"edges\"].append({\"source\": fid, \"target\": sub_node[\"id\"], \"relation\": relation, \"confidence\": \"EXTRACTED\",\n                             \"source_file\": rel, \"source_location\": \"\"})\n        saved_note = f\"\\n(saved copy: {base / safe})\" if base and cat else \"\"\n        if sub_res.get(\"text\"):\n            texts.append(f\"## {heading}: {safe}{saved_note}\\n{sub_res['text'][:3000000]}\")\n        elif cat == \"image\" and saved_note and not sub_node.get(\"decorative\"):\n            texts.append(f\"## {heading}: {safe}{saved_note}\\n(image without OCR text — view the saved copy)\")\n    # a name-only attachment node is superseded when the same attachment was read by content\n    read_names = {n[\"id\"].split(\"!/\", 1)[-1] for n in res[\"nodes\"] if n.get(\"attachment_of\") == rel}\n    drop = {n[\"id\"] for n in res[\"nodes\"]\n            if n.get(\"type\") == \"attachment\" and not n.get(\"content_sha\")\n            and re.sub(r'[\\\\/:*?\"<>|]+', \"_\", n[\"label\"]).strip() in read_names}\n    if drop:\n        res[\"nodes\"] = [n for n in res[\"nodes\"] if n[\"id\"] not in drop]\n        res[\"edges\"] = [e for e in res[\"edges\"] if e[\"source\"] not in drop and e[\"target\"] not in drop]\n        res[\"pending\"] = [p for p in res[\"pending\"] if p.get(\"source\") not in drop]\n    return \"\\n\\n\".join(texts)\n\n\n# ------------------------------------------------------------------ OpenDocument, RTF, EPUB, TeX/Org\n\ndef extract_odf(rel, abs_path):\n    doc = legacy.odf_document(Path(abs_path).read_bytes())\n    if doc[\"kind\"] == \"spreadsheet\":\n        res = {\"nodes\": [_doc(rel, \"workbook\")], \"edges\": [], \"pending\": []}\n        _ids, text = _sheet_nodes(rel, res, doc[\"sheets\"])\n        res[\"text\"] = text\n        return res\n    if doc[\"kind\"] == \"presentation\":\n        return _slides(rel, doc[\"slides\"])\n    return _markdownish(rel, doc[\"text\"], \"document\")\n\n\ndef extract_rtf(rel, abs_path):\n    return _markdownish(rel, legacy.rtf_text(Path(abs_path).read_bytes().decode(\"latin-1\")), \"document\")\n\n\ndef extract_epub(rel, abs_path):\n    return _markdownish(rel, legacy.epub_text(Path(abs_path).read_bytes()), \"document\")\n\n\ndef tex_org_to_markdown(rel, text):\n    if rel.lower().endswith(\".tex\"):\n        levels = {\"part\": 1, \"chapter\": 1, \"section\": 2, \"subsection\": 3, \"subsubsection\": 4}\n        text = re.sub(r\"\\\\(part|chapter|section|subsection|subsubsection)\\*?\\{([^}]*)\\}\",\n                      lambda m: \"\\n\" + \"#\" * levels[m.group(1)] + \" \" + m.group(2) + \"\\n\", text)\n        text = re.sub(r\"\\\\href\\{([^}]*)\\}\\{([^}]*)\\}\", r\"[\\2](\\1)\", text)\n        text = re.sub(r\"\\\\(?:input|include)\\{([^}]*)\\}\", r\"[\\1](\\1.tex)\", text)\n    elif rel.lower().endswith(\".org\"):\n        text = re.sub(r\"^(\\*+)\\s+\", lambda m: \"#\" * min(6, len(m.group(1))) + \" \", text, flags=re.M)\n        text = re.sub(r\"\\[\\[([^\\]]+)\\]\\[([^\\]]+)\\]\\]\", r\"[\\2](\\1)\", text)\n    elif rel.lower().endswith((\".razor\", \".cshtml\")):\n        text = re.sub(r\"@(?:model|inject|using)\\s+([\\w.<>]+)\", r\"`\\1`\", text)\n    return text\n\n\n# ------------------------------------------------------------------ data files\n\ndef extract_csv(rel, abs_path):\n    raw = read_text(abs_path, limit=5_000_000)\n    rows, total = legacy.csv_table(raw, rel)\n    res = {\"nodes\": [_doc(rel, \"table\")], \"edges\": [], \"pending\": []}\n    res[\"nodes\"][0][\"rows\"] = total\n    if rows:\n        for ci, val in enumerate(rows[0][:60]):\n            if str(val).strip():\n                cid = sym_id(rel, f\"col:{ci}\")\n                res[\"nodes\"].append({\"id\": cid, \"label\": f\"{sanitize_label(val, 80)} [{rel.rsplit('/', 1)[-1]}]\",\n                                     \"type\": \"column\", \"source_file\": rel, \"source_location\": f\"column {ci + 1}\"})\n                res[\"edges\"].append({\"source\": file_id(rel), \"target\": cid, \"relation\": \"has_column\",\n                                     \"confidence\": \"EXTRACTED\", \"source_file\": rel, \"source_location\": \"\"})\n    res[\"text\"] = \"\\n\".join(\" | \".join(r) for r in rows)\n    return res\n\n\ndef extract_ipynb(rel, abs_path):\n    lang, code, md = legacy.ipynb_cells(read_text(abs_path))\n    res = extract_code.extract(rel, code, \"python\" if \"python\" in (lang or \"python\").lower() else lang) \\\n        if code.strip() else {\"nodes\": [_doc(rel, \"file\")], \"edges\": [], \"pending\": []}\n    res[\"nodes\"][0].update(type=\"notebook\", lang=lang)\n    if md.strip():\n        _text_features(rel, md, res)\n    res[\"text\"] = md + \"\\n\\n```\\n\" + code[:20000] + \"\\n```\"\n    return res\n\n\ndef extract_sqlite(rel, abs_path):\n    res = {\"nodes\": [_doc(rel, \"database\")], \"edges\": [], \"pending\": []}\n    with open(abs_path, \"rb\") as fh:\n        if fh.read(16) != b\"SQLite format 3\\x00\":\n            return res\n    fid = file_id(rel)\n    tables = legacy.sqlite_schema(abs_path)\n    ids = {}\n    for t in tables:\n        tid = sym_id(rel, t[\"name\"])\n        ids[t[\"name\"].lower()] = tid\n        res[\"nodes\"].append({\"id\": tid, \"label\": t[\"name\"], \"type\": t[\"type\"] if t[\"type\"] == \"view\" else \"table\",\n                             \"source_file\": rel, \"source_location\": \"schema\", \"rows\": t[\"rows\"],\n                             \"doc\": \", \".join(t[\"columns\"][:25])})\n        res[\"edges\"].append({\"source\": fid, \"target\": tid, \"relation\": \"contains\", \"confidence\": \"EXTRACTED\",\n                             \"source_file\": rel, \"source_location\": \"\"})\n    for t in tables:\n        for ref_table, col, ref_col in t[\"fks\"]:\n            if ref_table.lower() in ids:\n                res[\"edges\"].append({\"source\": ids[t[\"name\"].lower()], \"target\": ids[ref_table.lower()],\n                                     \"relation\": \"references\", \"confidence\": \"EXTRACTED\", \"source_file\": rel,\n                                     \"source_location\": f\"{col} → {ref_table}.{ref_col}\"})\n        if t[\"type\"] == \"view\":\n            for m in re.finditer(r\"\\b(?:FROM|JOIN)\\s+[\\\"`\\[]?(\\w+)\", t[\"sql\"], re.I):\n                if m.group(1).lower() in ids and m.group(1).lower() != t[\"name\"].lower():\n                    res[\"edges\"].append({\"source\": ids[t[\"name\"].lower()], \"target\": ids[m.group(1).lower()],\n                                         \"relation\": \"uses\", \"confidence\": \"EXTRACTED\", \"source_file\": rel,\n                                         \"source_location\": \"\"})\n    res[\"text\"] = \"\\n\".join(f\"{t['type']} {t['name']}({', '.join(t['columns'])})\" for t in tables)\n    return res\n\n\ndef extract_gshortcut(rel, abs_path):\n    res = {\"nodes\": [_doc(rel, \"cloud_document\")], \"edges\": [], \"pending\": []}\n    try:\n        data = json.loads(read_text(abs_path))\n        res[\"nodes\"][0][\"doc\"] = sanitize_label(data.get(\"url\") or data.get(\"doc_id\") or \"\", 200)\n    except ValueError:\n        pass\n    return res\n\n\ndef extract_visio(rel, abs_path):\n    \"\"\"Visio .vsdx: every page's shapes with their text, and the connectors between shapes (A → B), so\n    process maps and org charts drawn in Visio become readable flows.\"\"\"\n    import xml.etree.ElementTree as ET\n    node = _doc(rel, \"diagram\")\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": []}\n    parts = []\n    with zipfile.ZipFile(abs_path) as z:\n        names = z.namelist()\n        page_names = {}\n        if \"visio/pages/pages.xml\" in names:\n            rels = {}\n            if \"visio/pages/_rels/pages.xml.rels\" in names:\n                for r in ET.fromstring(z.read(\"visio/pages/_rels/pages.xml.rels\")):\n                    rels[r.get(\"Id\")] = \"visio/pages/\" + r.get(\"Target\", \"\").split(\"/\")[-1]\n            for pg in ET.fromstring(z.read(\"visio/pages/pages.xml\")):\n                rel_el = next((c for c in pg if c.tag.rsplit(\"}\", 1)[-1] == \"Rel\"), None)\n                rid = rel_el.get(\"{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id\") if rel_el is not None else None\n                if rid in rels:\n                    page_names[rels[rid]] = pg.get(\"NameU\") or pg.get(\"Name\") or rels[rid]\n        pages = sorted((n for n in names if re.match(r\"visio/pages/page\\d+\\.xml$\", n)),\n                       key=lambda n: int(re.search(r\"(\\d+)\", n.rsplit(\"/\", 1)[-1]).group(1)))\n        total_shapes = 0\n        for i, pth in enumerate(pages, 1):\n            root = ET.fromstring(z.read(pth))\n            texts = {}\n            for sh in root.iter():\n                if sh.tag.rsplit(\"}\", 1)[-1] != \"Shape\":\n                    continue\n                txt_el = next((c for c in sh if c.tag.rsplit(\"}\", 1)[-1] == \"Text\"), None)\n                if txt_el is not None:\n                    t = re.sub(r\"\\s+\", \" \", \"\".join(txt_el.itertext())).strip()\n                    if t:\n                        texts[sh.get(\"ID\")] = t\n            links = {}\n            for c in root.iter():\n                if c.tag.rsplit(\"}\", 1)[-1] == \"Connect\":\n                    links.setdefault(c.get(\"FromSheet\"), []).append((c.get(\"FromCell\", \"\"), c.get(\"ToSheet\")))\n            flows = []\n            for conn, ends in links.items():\n                begin = next((to for cell, to in ends if cell.startswith(\"Begin\")), None)\n                end = next((to for cell, to in ends if cell.startswith(\"End\")), None)\n                if begin in texts and end in texts:\n                    label = f\" [{texts[conn]}]\" if conn in texts else \"\"\n                    flows.append(f\"{texts[begin]} → {texts[end]}{label}\")\n            total_shapes += len(texts)\n            title = page_names.get(pth, f\"Page {i}\")\n            block = [f\"## Page {i}: {title}\"] + [t for sid, t in texts.items()]\n            if flows:\n                block += [\"### Connections\"] + flows\n            parts.append(\"\\n\".join(block))\n            pid = sym_id(rel, f\"page{i}\")\n            res[\"nodes\"].append({\"id\": pid, \"label\": f\"Page {i}: {title}\", \"type\": \"page\", \"source_file\": rel,\n                                 \"source_location\": f\"page {i}\"})\n            res[\"edges\"].append({\"source\": file_id(rel), \"target\": pid, \"relation\": \"contains\",\n                                 \"confidence\": \"EXTRACTED\", \"source_file\": rel, \"source_location\": \"\"})\n        node[\"pages\"] = len(pages)\n        node[\"shapes_with_text\"] = total_shapes\n    res[\"text\"] = \"\\n\\n\".join(parts)\n    return res\n\n\ndef extract_onenote(rel, abs_path):\n    \"\"\"OneNote .one is an undocumented binary store: recover its readable text runs (UTF-16LE strings) so the\n    notes are searchable. Layout, ink and images are not recovered — flagged as partial.\"\"\"\n    data = Path(abs_path).read_bytes()\n    runs, seen = [], set()\n    for m in re.finditer(rb\"(?:[\\x20-\\x7e\\x0a\\x0d\\x09]\\x00|[\\x00-\\xff][\\x06\\x05\\x04\\x20\\x22\\xfb\\xfe])\"\n                         rb\"{6,}\", data):\n        try:\n            s = m.group(0).decode(\"utf-16-le\", errors=\"ignore\")\n        except Exception:\n            continue\n        s = re.sub(r\"[\\x00-\\x08\\x0b-\\x1f]\", \"\", s).strip()\n        letters = sum(ch.isalpha() for ch in s)\n        if len(s) >= 4 and letters >= 0.5 * len(s.replace(\" \", \"\")) and s not in seen:\n            seen.add(s)\n            runs.append(s)\n    node = _doc(rel, \"document\")\n    node[\"partial_text\"] = True\n    node[\"note\"] = \"OneNote binary: text runs recovered; layout, ink and pictures are not. Export to PDF/DOCX for full fidelity.\"\n    text = \"\\n\".join(runs)\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": [], \"text\": text}\n    if text:\n        _text_features(rel, text, res)\n    return res\n\n\nARCHIVE_MAX_MEMBERS = 20000\nARCHIVE_MAX_MEMBER_BYTES = 2_000_000_000\nARCHIVE_MAX_TOTAL_BYTES = 8_000_000_000   # guards against decompression bombs\n\n\ndef _archive_members(abs_path):\n    \"\"\"Yield (name, size, read_bytes_callable) for every file inside an archive, using stdlib readers for\n    zip/tar/gz/bz2/xz and the OS libarchive (Windows tar.exe / bsdtar) or 7-Zip for 7z/rar/cab/iso.\n    Raises RuntimeError with a readable reason when the archive cannot be opened.\"\"\"\n    import bz2\n    import gzip\n    import lzma\n    import tarfile\n    low = str(abs_path).lower()\n    if zipfile.is_zipfile(abs_path):\n        z = zipfile.ZipFile(abs_path)\n        for info in z.infolist():\n            if info.is_dir():\n                continue\n            if info.flag_bits & 0x1:\n                yield info.filename, info.file_size, None  # password-protected member\n                continue\n            yield info.filename, info.file_size, (lambda i=info: z.read(i))\n        return\n    try:\n        if tarfile.is_tarfile(abs_path):\n            with tarfile.open(abs_path) as tf:\n                for m in tf.getmembers():\n                    if m.isfile():\n                        yield m.name, m.size, (lambda mm=m, t=tf: t.extractfile(mm).read())\n            return\n    except (tarfile.TarError, OSError):\n        pass\n    single = {\".gz\": gzip.open, \".bz2\": bz2.open, \".xz\": lzma.open}\n    for ext, opener in single.items():\n        if low.endswith(ext) and not low.endswith(\".tar\" + ext):\n            inner = Path(abs_path).name[: -len(ext)] or \"content\"\n            def read(o=opener):\n                with o(abs_path, \"rb\") as fh:\n                    return fh.read(ARCHIVE_MAX_MEMBER_BYTES + 1)\n            yield inner, -1, read\n            return\n    tool = native.sevenzip() or native.bsdtar()\n    if not tool:\n        raise RuntimeError(\"no archive tool for this format (install 7-Zip, or use Windows 10+ / macOS tar)\")\n    tmp = Path(tempfile.mkdtemp(prefix=\"kgraph_arc_\"))\n    try:\n        if \"7z\" in Path(tool).name.lower():\n            code, _o, err = native.run([tool, \"x\", \"-y\", \"-p\", f\"-o{tmp}\", str(abs_path)], timeout=3600)\n        else:\n            code, _o, err = native.run([tool, \"-xf\", str(abs_path), \"-C\", str(tmp)], timeout=3600)\n        files = [p for p in tmp.rglob(\"*\") if p.is_file()]\n        if code != 0 and not files:\n            msg = (err or b\"\").decode(\"utf-8\", errors=\"replace\").strip()[-300:]\n            raise RuntimeError((\"password-protected or unsupported archive: \" + msg) if msg else \"archive could not be opened\")\n        for p in files:\n            yield p.relative_to(tmp).as_posix(), p.stat().st_size, (lambda pp=p: pp.read_bytes())\n    finally:\n        shutil.rmtree(tmp, ignore_errors=True)\n\n\ndef extract_archive(rel, abs_path, ctx):\n    \"\"\"Every member is extracted with the normal extractors (documents, PDFs, sheets, images with OCR, media,\n    nested archives up to 2 levels) and linked with `contains`; members that cannot be read are listed.\"\"\"\n    from .detect import categorize\n    ctx = ctx or {}\n    node = _doc(rel, \"archive\")\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": []}\n    listing, skipped, texts = [], [], []\n    total = count = 0\n    depth = ctx.get(\"attachment_depth\", 0)\n    try:\n        for name, size, reader in _archive_members(abs_path):\n            count += 1\n            listing.append(f\"{name} ({size if size >= 0 else '?'} bytes)\")\n            if count > ARCHIVE_MAX_MEMBERS:\n                skipped.append(f\"{name}: member limit reached\")\n                continue\n            cat, _lang = categorize(Path(name))\n            if reader is None:\n                skipped.append(f\"{name}: password-protected\")\n                continue\n            if size > ARCHIVE_MAX_MEMBER_BYTES or total + max(size, 0) > ARCHIVE_MAX_TOTAL_BYTES:\n                skipped.append(f\"{name}: too large to unpack safely\")\n                continue\n            try:\n                data = reader()\n            except Exception as exc:\n                skipped.append(f\"{name}: unreadable ({exc.__class__.__name__})\")\n                continue\n            total += len(data)\n            if not cat:\n                from .detect import sniff_text\n                probe = Path(tempfile.mkdtemp(prefix=\"kgraph_probe_\")) / \"p\"\n                probe.write_bytes(data[:65536])\n                is_text = sniff_text(probe)\n                shutil.rmtree(probe.parent, ignore_errors=True)\n                if not is_text:\n                    skipped.append(f\"{name}: unsupported binary type\")\n                    continue\n                name = name + \".txt\"  # plain text with an unknown extension\n            if depth >= 2 and cat == \"archive\":\n                skipped.append(f\"{name}: nested archive deeper than 2 levels\")\n                continue\n            text = _extract_attachments(rel, [(name.replace(\"/\", \"__\"), data)], ctx, res, depth,\n                                        heading=\"Archive member\", relation=\"contains\")\n            if text:\n                texts.append(text)\n    except RuntimeError as exc:\n        node[\"error\"] = str(exc)[:300]\n        node[\"unreadable\"] = True\n    node[\"members\"] = count\n    if skipped:\n        node[\"skipped_members\"] = skipped[:200]\n    header = \"Archive members:\\n\" + \"\\n\".join(listing[:2000])\n    if skipped:\n        header += \"\\n\\nNot read:\\n\" + \"\\n\".join(skipped[:500])\n    res[\"text\"] = header + (\"\\n\\n\" + \"\\n\\n\".join(texts) if texts else \"\")\n    return res\n\n\n# ------------------------------------------------------------------ PDF with OCR fallback, images, media\n\n_GARBLE_RX = re.compile(\"[�--ƒ‚-„†-•…‰‹›\"\n                        '\\u0152\\u0153\\u0160\\u0161\\u0178\\u017d\\u017e\\u02c6\\u02dc\\u2122\\u066e\\u066f\\u06a1\\u06ba]')\n\n\ndef garble_ratio(text):\n    \"\"\"Share of non-space characters that signal a broken font mapping (cp1252 symbol soup, replacement\n    characters, private-use glyphs, dotless Arabic letters).\"\"\"\n    chars = [c for c in (text or \"\") if not c.isspace()]\n    if len(chars) < 20:\n        return 0.0\n    return len(_GARBLE_RX.findall(\"\".join(chars))) / len(chars)\n\n\ndef extract_pdf(rel, abs_path, ctx):\n    from .extract_docs import _common_doc_features\n    data = Path(abs_path).read_bytes()\n    try:\n        parsed = pdfparse.extract(data)\n    except Exception as exc:\n        parsed = {\"pages\": [], \"page_count\": 0, \"image_pages\": [], \"encrypted\": False, \"title\": \"\", \"error\": str(exc)}\n    fid = file_id(rel)\n    node = _doc(rel, \"document\")\n    node[\"pages\"] = parsed.get(\"page_count\", 0)\n    pages = list(parsed.get(\"pages\") or [])\n    garbled = [i for i, p in enumerate(pages, 1) if garble_ratio(p) > 0.12]\n    if garbled:\n        node[\"garbled_text_pages\"] = garbled[:200]  # text layer without a usable Unicode map: OCR replaces it\n    diagram = parsed.get(\"diagram_pages\") or []\n    if parsed.get(\"table_pages\"):\n        node[\"table_pages\"] = parsed[\"table_pages\"][:200]  # rebuilt row by row with \" │ \" between cells\n    if parsed.get(\"brackets_premirrored\"):\n        node[\"pdf_producer_note\"] = \"RTL brackets stored logically by the producer (mirroring skipped)\"\n    if diagram:\n        # flow charts / process maps / org charts: text is rebuilt box-by-box, but arrows and swimlanes only\n        # exist visually — render the pages and ask the agent to look at them\n        node[\"diagram_pages\"] = diagram[:200]\n    no_text = not \"\".join(pages).strip()\n    if len(diagram) > 60:\n        # slide decks where nearly every page is a layout: the box-by-box text is kept, but rendering and\n        # viewing hundreds of pages is not proportionate — the reader can render specific pages on demand\n        node[\"diagram_note\"] = f\"{len(diagram)} layout pages; not rendered automatically (view selectively)\"\n        diagram = []\n    need_ocr = parsed.get(\"encrypted\") or parsed.get(\"image_pages\") or garbled or diagram or (no_text and data)\n    engine = None\n    if need_ocr and ctx.get(\"ocr\", True) and ocr.available():\n        pages_dir = Path(ctx[\"frames_dir\"]).parent / \"pages\" / slug(rel, 120) if ctx.get(\"frames_dir\") else None\n        max_ocr = ctx.get(\"max_ocr_pages\", 60)\n        # only the pages that need it: a 245-page text PDF with 2 garbled pages reads 2 pages, not 245\n        if no_text or parsed.get(\"encrypted\"):\n            ocr_pages = None\n        else:\n            wanted = sorted(set(parsed.get(\"image_pages\") or []) | set(garbled) | set(diagram))\n            ocr_pages = wanted[:max_ocr]\n            if len(wanted) > max_ocr:\n                node[\"needs_vision\"] = True\n                node[\"ocr_note\"] = f\"{len(wanted) - max_ocr} further pages needing OCR not read (raise --max-ocr-pages)\"\n        o = ocr.ocr_file(abs_path, ctx.get(\"ocr_cache\"), max_pages=max_ocr, save_dir=pages_dir, pages=ocr_pages)\n        if o and o.get(\"pages\"):\n            engine = o.get(\"engine\")\n            node[\"ocr_quality\"] = o.get(\"quality\")\n            images = [p.get(\"image\") for p in o[\"pages\"] if p.get(\"image\")]\n            if images:\n                node[\"page_images\"] = str(pages_dir)\n            weak = [p[\"page\"] for p in o[\"pages\"] if p.get(\"quality\", 1) < 0.6 or len(p[\"text\"].strip()) < 20]\n            if weak:\n                node[\"needs_vision\"] = True  # OCR is junk/sparse here: the agent should look at the page images\n                node[\"weak_ocr_pages\"] = weak[:50]\n            by_page = {p[\"page\"]: p[\"text\"] for p in o[\"pages\"]}\n            if not pages:\n                pages = [by_page.get(i, \"\") for i in range(1, (o.get(\"page_count\") or len(by_page)) + 1)]\n                node[\"pages\"] = len(pages)\n            targets = parsed.get(\"image_pages\") or (range(1, len(pages) + 1) if (no_text or parsed.get(\"encrypted\")) else [])\n            for pno in targets:\n                if pno in by_page and len(by_page[pno].strip()) > len(pages[pno - 1].strip()):\n                    pages[pno - 1] = by_page[pno]\n            for pno in garbled:\n                if pno in by_page and pno <= len(pages) and garble_ratio(by_page[pno]) < garble_ratio(pages[pno - 1]):\n                    pages[pno - 1] = by_page[pno]\n            if diagram and images:\n                node[\"needs_vision\"] = True\n            unocr = [p for p in garbled if p not in by_page]\n            if unocr:\n                node[\"needs_vision\"] = True\n                node[\"weak_ocr_pages\"] = sorted(set((node.get(\"weak_ocr_pages\") or []) + unocr))[:50]\n            rotated = [p[\"page\"] for p in o[\"pages\"] if p.get(\"rotated\")]\n            if rotated:\n                node[\"rotated_pages\"] = rotated[:200]  # sideways scans, read (and saved) upright\n            if node.get(\"needs_vision\") and images and pages_dir:\n                # review many pages in a few images: weak/diagram pages first, then the rest that were rendered\n                focus = set(node.get(\"weak_ocr_pages\") or []) | set(diagram or [])\n                shown = [p for p in o[\"pages\"] if p.get(\"image\")]\n                shown.sort(key=lambda p: (p[\"page\"] not in focus, p[\"page\"]))\n                sheets = ocr.page_sheets([(p[\"image\"], f\"p.{p['page']}\" + (\" (weak OCR)\" if p[\"page\"] in (node.get(\"weak_ocr_pages\") or []) else \"\"))\n                                          for p in shown[:120]], Path(pages_dir) / \"sheet\")\n                if sheets:\n                    node[\"page_sheets\"] = sheets\n    if engine:\n        node[\"ocr\"] = engine\n    if parsed.get(\"image_pages\") and not engine:\n        node[\"needs_vision\"] = True  # scanned pages without a local OCR engine: agent vision in semantic pass\n    if parsed.get(\"encrypted\") and not engine:\n        node[\"encrypted\"] = True\n    text = \"\\n\\n\".join(f\"<!-- page {i} -->\\n{p}\" for i, p in enumerate(pages, 1) if p.strip())\n    title = parsed.get(\"title\") or next((ln.strip() for ln in text.splitlines() if len(ln.strip()) > 8 and not ln.startswith(\"<!--\")), \"\")\n    if title:\n        node[\"doc\"] = sanitize_label(title, 160)\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": []}\n    if text.strip():\n        from .extract_docs import extract_markdown\n        md = promote_numbered_headings(re.sub(r\"^<!-- page \\d+ -->\\n\", \"\", text, flags=re.M))\n        structured = extract_markdown(rel, md)  # sections from numbered headings + links/mentions/citations\n        structured[\"nodes\"][0] = dict(node, **{k: v for k, v in structured[\"nodes\"][0].items() if k == \"doc\" and not node.get(\"doc\")})\n        res = {\"nodes\": structured[\"nodes\"], \"edges\": structured[\"edges\"], \"pending\": structured[\"pending\"]}\n        _mention_identifiers(rel, text, res, noisy=bool(engine))\n    res[\"text\"] = text\n    return res\n\n\ndef extract_image(rel, abs_path, ctx):\n    node = _doc(rel, \"image\")\n    info = media.image_info(abs_path)\n    for k in (\"width\", \"height\", \"description\", \"camera_model\", \"datetime\", \"software\"):\n        if info.get(k):\n            node[k] = info[k]\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": []}\n    text = \"\"\n    size = Path(abs_path).stat().st_size\n    suffix = Path(abs_path).suffix.lower()\n    if ctx.get(\"attachment_depth\") and size < DECORATIVE_BYTES:\n        node[\"decorative\"] = True  # signature icon / spacer inside an email: nothing to read\n        res[\"text\"] = \"\"\n        return res\n    if ctx.get(\"ocr\", True) and ocr.available() and (suffix in ocr.IMAGE_EXT or suffix in OCRABLE):\n        target = abs_path\n        if suffix in (\".emz\", \".wmz\") and ctx.get(\"frames_dir\"):\n            target = _materialize_image(abs_path, Path(ctx[\"frames_dir\"]).parent / \"embedded\" / (slug(rel, 120) + suffix))\n        o = ocr.ocr_many([str(target)], ctx.get(\"ocr_cache\")).get(str(target)) if target else None\n        text = (o or {}).get(\"text\", \"\").strip()\n        if o and o.get(\"engine\"):\n            node[\"ocr\"] = o[\"engine\"]\n            node[\"ocr_quality\"] = o.get(\"quality\")\n        if not text or (o or {}).get(\"quality\", 0) < 0.6:\n            node[\"needs_vision\"] = True\n    else:\n        node[\"needs_vision\"] = True\n    if text:\n        first = next((ln for ln in text.splitlines() if len(ln.strip()) > 3), \"\")\n        node[\"doc\"] = sanitize_label(first, 160)\n        _text_features(rel, text, res)\n        _mention_identifiers(rel, text, res, noisy=True)\n    res[\"text\"] = text\n    return res\n\n\ndef _mention_identifiers(rel, text, res, noisy=False):\n    \"\"\"Screenshots/diagrams rarely use backticks: treat CamelCase / snake_case tokens as possible symbol mentions.\n    noisy=True (OCR, speech transcripts): also scan the whole text with spacing/case/OCR-confusion-insensitive\n    matching against symbol and sheet names (\"Send TrainingPIan\" → SendTrainingPlan, \"datasheet\" → Data Sheet).\"\"\"\n    if noisy and text.strip():\n        res[\"pending\"].append({\"kind\": \"text_scan\", \"source\": file_id(rel), \"text\": text[:60000], \"file\": rel})\n    seen = set()\n    for m in re.finditer(r\"\\b([A-Z][a-z]+(?:[A-Z][a-z0-9]+)+|[a-z]+(?:_[a-z0-9]+)+|[a-z]+[A-Z]\\w+)\\b\", text):\n        name = m.group(1)\n        if name.lower() in seen or len(name) < 5:\n            continue\n        seen.add(name.lower())\n        res[\"pending\"].append({\"kind\": \"mention\", \"source\": file_id(rel), \"name\": name, \"file\": rel})\n\n\ndef extract_media(rel, abs_path, ctx):\n    info = media.media_info(abs_path)\n    kind = \"video\" if Path(abs_path).suffix.lower() in media.VIDEO_EXT else \"audio\"\n    node = _doc(rel, kind)\n    for k in (\"duration\", \"title\", \"artist\", \"album\", \"comment\", \"description\", \"date\"):\n        if info.get(k):\n            node[k] = info[k]\n    res = {\"nodes\": [node], \"edges\": [], \"pending\": []}\n    parts = []\n    if ctx.get(\"media\", True):\n        tr = media.transcribe(abs_path, ctx.get(\"transcript_cache\"), info.get(\"duration\"))\n        conf = tr.get(\"confidence\")\n        dictation = \"System.Speech\" in str(tr.get(\"engine\") or \"\") and \"sidecar\" not in str(tr.get(\"engine\") or \"\")\n        if tr.get(\"text\") and dictation and conf is not None and conf < media.MIN_DICTATION_CONFIDENCE:\n            # Windows dictation forces every sound into its installed language; at this confidence the\n            # \"transcript\" is noise (typically speech in a language with no installed recognizer, e.g. Arabic)\n            node[\"speech_unrecognized\"] = True\n            node[\"transcript_confidence\"] = conf\n            node[\"installed_speech_languages\"] = \", \".join(tr.get(\"installed_languages\") or []) or \"unknown\"\n            node[\"needs_transcript\"] = True\n            parts.append(\"## Speech\\nSpeech was detected but could not be transcribed reliably offline \"\n                         f\"(engine {tr.get('engine')}, confidence {conf}; installed speech languages: \"\n                         f\"{node['installed_speech_languages']}). The noise output was discarded. To transcribe: \"\n                         \"add a subtitle file next to the video (same name .srt/.vtt/.txt), or install an offline \"\n                         \"Whisper engine (faster-whisper / whisper.cpp) — see references/file-formats.md.\")\n        elif tr.get(\"text\"):\n            node[\"transcript_engine\"] = tr.get(\"engine\")\n            if tr.get(\"confidence\") is not None:\n                node[\"transcript_confidence\"] = tr[\"confidence\"]\n            if tr.get(\"note\"):\n                node[\"transcript_note\"] = tr[\"note\"]\n            header = f\"## Transcript ({tr.get('engine')}\" + (f\", avg confidence {tr['confidence']}\" if tr.get(\"confidence\") is not None else \"\") + \")\"\n            parts.append(header + (\"\\n\" + tr[\"note\"] if tr.get(\"note\") else \"\") + \"\\n\" + tr[\"text\"])\n        elif tr.get(\"errors\"):\n            node[\"transcript_error\"] = \"; \".join(tr[\"errors\"])[:300]\n        if kind == \"video\" and ctx.get(\"ocr\", True):\n            frame_dir = Path(ctx[\"frames_dir\"]) / slug(rel, 120) if ctx.get(\"frames_dir\") else None\n            if frame_dir:\n                # /watch-style sampling: budget scaled by duration (capped by --frames), near-identical frames\n                # dropped, timestamped names and a contact sheet for one-look viewing\n                from . import watch as watch_tool\n                frames, sheet, dropped = [], None, 0\n                try:\n                    duration = float(node.get(\"duration\") or 0)\n                    times, _fps, _focused = watch_tool.frame_times(duration, max_frames=ctx.get(\"frames\", 24)) \\\n                        if duration else ([], 0, False)\n                    if times:\n                        fr = watch_tool.extract_frames(abs_path, frame_dir, times, max_width=768)\n                        frames = [f[\"path\"] for f in fr[\"frames\"]]\n                        sheet, dropped = fr.get(\"contact_sheet\"), fr.get(\"dropped_similar\", 0)\n                        index = [f\"- t={watch_tool.fmt_time(f['time'])} {Path(f['path']).name}\" for f in fr[\"frames\"]]\n                except Exception as exc:\n                    node[\"frames_error\"] = str(exc)[:200]\n                if not frames:\n                    frames = media.video_frames(abs_path, frame_dir, min(ctx.get(\"frames\", 24), 6))\n                    index = [f\"- {Path(p).name}\" for p in frames]\n                if frames:\n                    node[\"frames\"] = len(frames)\n                    node[\"frames_dir\"] = str(frame_dir)\n                    if sheet:\n                        node[\"contact_sheet\"] = sheet\n                    if dropped:\n                        node[\"frames_dropped_similar\"] = dropped\n                    node[\"needs_vision\"] = node.get(\"needs_vision\") or bool(node.get(\"speech_unrecognized\"))\n                    parts.append(\"## Key frames (timestamped; view the contact sheet\"\n                                 + (f\": {sheet}\" if sheet else \"\") + \")\\n\" + \"\\n\".join(index))\n                    seen_text = media.frames_ocr(frames, ctx.get(\"ocr_cache\")) if ocr.available() else \"\"\n                    if seen_text:\n                        parts.append(\"## On-screen text (OCR of key frames)\\n\" + seen_text)\n    text = \"\\n\\n\".join(parts)\n    if node.get(\"title\"):\n        node[\"doc\"] = sanitize_label(node[\"title\"], 160)\n    if text:\n        _text_features(rel, text, res)\n        _mention_identifiers(rel, text, res, noisy=True)\n    res[\"text\"] = text\n    return res\n\n\n# ------------------------------------------------------------------ project / build files\n\ndef extract_project_file(rel, text, res):\n    \"\"\"Enrich config extraction for .csproj/.sln/pom/gradle/Dockerfile/compose/Makefile/XAML.\"\"\"\n    from .extract_docs import _link_pending, _pkg\n    low = rel.lower()\n    name = low.rsplit(\"/\", 1)[-1]\n    fid = file_id(rel)\n    if low.endswith((\".csproj\", \".vbproj\", \".fsproj\", \".props\", \".targets\")):\n        for m in re.finditer(r'<ProjectReference\\s+Include=\"([^\"]+)\"', text):\n            p = _link_pending(fid, rel, m.group(1).replace(\"\\\\\", \"/\"), None)\n            if p:\n                res[\"pending\"].append(dict(p, relation=\"references_project\"))\n        for m in re.finditer(r'<PackageReference\\s+Include=\"([^\"]+)\"', text):\n            _pkg(res[\"nodes\"], res[\"edges\"], rel, m.group(1))\n    elif low.endswith(\".sln\"):\n        for m in re.finditer(r'Project\\(\"[^\"]*\"\\)\\s*=\\s*\"([^\"]+)\",\\s*\"([^\"]+)\"', text):\n            p = _link_pending(fid, rel, m.group(2).replace(\"\\\\\", \"/\"), None)\n            if p:\n                res[\"pending\"].append(p)\n    elif name == \"pom.xml\":\n        for m in re.finditer(r\"<dependency>\\s*<groupId>([^<]+)</groupId>\\s*<artifactId>([^<]+)</artifactId>\", text):\n            _pkg(res[\"nodes\"], res[\"edges\"], rel, f\"{m.group(1)}:{m.group(2)}\")\n        m = re.search(r\"<artifactId>([^<]+)</artifactId>\", text)\n        if m:\n            _pkg(res[\"nodes\"], res[\"edges\"], rel, m.group(1), \"defines\")\n    elif name.startswith((\"build.gradle\", \"settings.gradle\")):\n        for m in re.finditer(r\"(?:implementation|api|compile|testImplementation|runtimeOnly)\\s*\\(?\\s*['\\\"]([^'\\\":]+:[^'\\\":]+)\", text):\n            _pkg(res[\"nodes\"], res[\"edges\"], rel, m.group(1))\n    elif name.startswith((\"dockerfile\", \"containerfile\")):\n        for m in re.finditer(r\"^\\s*FROM\\s+(?:--platform=\\S+\\s+)?(\\S+)\", text, re.M | re.I):\n            _pkg(res[\"nodes\"], res[\"edges\"], rel, m.group(1).split(\"@\")[0], \"based_on\")\n        for m in re.finditer(r\"^\\s*(?:COPY|ADD)\\s+(?:--\\S+\\s+)*(\\S+)\", text, re.M | re.I):\n            p = _link_pending(fid, rel, m.group(1), None)\n            if p and \".\" in m.group(1):\n                res[\"pending\"].append(dict(p, relation=\"copies\"))\n    elif name.startswith((\"docker-compose\", \"compose\")):\n        svc_block = re.search(r\"^services:\\s*\\n((?:[ \\t]+.*\\n?)+)\", text, re.M)\n        if svc_block:\n            services = re.findall(r\"^  ([\\w.\\-]+):\\s*$\", svc_block.group(1), re.M)\n            for s in services:\n                sid = sym_id(rel, \"service:\" + s)\n                res[\"nodes\"].append({\"id\": sid, \"label\": f\"{s} (service)\", \"type\": \"service\", \"source_file\": rel,\n                                     \"source_location\": \"\"})\n                res[\"edges\"].append({\"source\": fid, \"target\": sid, \"relation\": \"defines\", \"confidence\": \"EXTRACTED\",\n                                     \"source_file\": rel, \"source_location\": \"\"})\n            for s_match in re.finditer(r\"^  ([\\w.\\-]+):\\s*\\n((?:    .*\\n?)*)\", svc_block.group(1), re.M):\n                body = s_match.group(2)\n                img = re.search(r\"^\\s+image:\\s*(\\S+)\", body, re.M)\n                if img:\n                    _pkg(res[\"nodes\"], res[\"edges\"], rel, img.group(1), \"runs\", sym_id(rel, \"service:\" + s_match.group(1)))\n                dep = re.search(r\"^\\s+depends_on:\\s*\\n((?:\\s+-\\s*\\S+\\n?)+)\", body, re.M)\n                for d in re.findall(r\"-\\s*(\\S+)\", dep.group(1)) if dep else []:\n                    if d in services:\n                        res[\"edges\"].append({\"source\": sym_id(rel, \"service:\" + s_match.group(1)), \"target\": sym_id(rel, \"service:\" + d),\n                                             \"relation\": \"depends_on\", \"confidence\": \"EXTRACTED\", \"source_file\": rel,\n                                             \"source_location\": \"\"})\n    elif name in (\"makefile\", \"gnumakefile\") or low.endswith(\".mk\"):\n        targets = {}\n        for m in re.finditer(r\"^([\\w.\\-/]+)\\s*:(?!=)\\s*([^\\n#]*)\", text, re.M):\n            t = m.group(1)\n            tid = sym_id(rel, \"target:\" + t)\n            targets[t] = tid\n            res[\"nodes\"].append({\"id\": tid, \"label\": f\"{t} (make target)\", \"type\": \"target\", \"source_file\": rel,\n                                 \"source_location\": f\"L{text.count(chr(10), 0, m.start()) + 1}\"})\n            res[\"edges\"].append({\"source\": fid, \"target\": tid, \"relation\": \"defines\", \"confidence\": \"EXTRACTED\",\n                                 \"source_file\": rel, \"source_location\": \"\"})\n            for dep in m.group(2).split():\n                res[\"pending\"].append({\"kind\": \"make_dep\", \"source\": tid, \"name\": dep, \"file\": rel})\n        for p in list(res[\"pending\"]):\n            if p.get(\"kind\") == \"make_dep\":\n                res[\"pending\"].remove(p)\n                if p[\"name\"] in targets:\n                    res[\"edges\"].append({\"source\": p[\"source\"], \"target\": targets[p[\"name\"]], \"relation\": \"depends_on\",\n                                         \"confidence\": \"EXTRACTED\", \"source_file\": rel, \"source_location\": \"\"})\n    elif low.endswith(\".xaml\"):\n        m = re.search(r'x:Class=\"([\\w.]+)\"', text)\n        if m:\n            res[\"nodes\"][0][\"doc\"] = f\"code-behind {m.group(1)}\"\n            res[\"pending\"].append({\"kind\": \"call\", \"source\": fid, \"name\": m.group(1).split(\".\")[-1], \"receiver\": None,\n                                   \"file\": rel, \"line\": 1, \"strict\": True, \"relation\": \"code_behind\"})\n        for h in set(re.findall(r'\\b(?:Click|Loaded|Checked|SelectionChanged|TextChanged|Command)=\"\\{?([A-Za-z_]\\w+)\\}?\"', text)):\n            res[\"pending\"].append({\"kind\": \"call\", \"source\": fid, \"name\": h, \"receiver\": None, \"file\": rel, \"line\": 1,\n                                   \"strict\": True, \"relation\": \"handled_by\"})\n    elif low.endswith(\".toc\"):\n        for ln in text.splitlines():\n            ln = ln.strip()\n            if ln and not ln.startswith(\"#\"):\n                p = _link_pending(fid, rel, ln.replace(\"\\\\\", \"/\"), None)\n                if p:\n                    res[\"pending\"].append(dict(p, relation=\"loads\"))\n    return res\n");
